import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.BhkMvQqH.js";const u=JSON.parse('{"title":"Proposal: Frontend Screen Analysis — Bookia SaaS","description":"","frontmatter":{},"headers":[],"relativePath":"changes/screen-analysis/proposal.md","filePath":"changes/screen-analysis/proposal.md"}'),r={name:"changes/screen-analysis/proposal.md"};function n(d,e,l,s,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="proposal-frontend-screen-analysis-—-bookia-saas" tabindex="-1">Proposal: Frontend Screen Analysis — Bookia SaaS <a class="header-anchor" href="#proposal-frontend-screen-analysis-—-bookia-saas" aria-label="Permalink to &quot;Proposal: Frontend Screen Analysis — Bookia SaaS&quot;">​</a></h1><h2 id="intent" tabindex="-1">Intent <a class="header-anchor" href="#intent" aria-label="Permalink to &quot;Intent&quot;">​</a></h2><p>Define a complete frontend screen inventory from Bookia&#39;s ~30-table data model. The project is a blank React 19 + Vite JS canvas (Supabase Auth only). This analysis bridges data model → screens, enabling a future Angular frontend implementation, UI/UX component planning, and effort estimation.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><h3 id="in-scope" tabindex="-1">In Scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to &quot;In Scope&quot;">​</a></h3><ul><li>71 screens derived from ~30 tables across 11 domains</li><li>CRUD analysis per screen (Create/Read/Update/Delete/List/specialized)</li><li>Permission mapping: <code>SystemMenu</code> transaction codes → <code>OrganizationRoleMenu</code> read/write/delete → <code>PlanMenu</code> subscription gating</li><li>Navigation tree mirroring <code>SystemMenu</code> hierarchy</li><li>CRM privacy fallback patterns (local field → global field for emails/phones)</li><li>Calendar availability engine constraints and real-time requirements</li></ul><h3 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No code generation, routing, UI library, or test framework decisions</li><li>No DB migrations or backend changes</li><li>No migration specs for existing data</li></ul><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><h3 id="new-capabilities" tabindex="-1">New Capabilities <a class="header-anchor" href="#new-capabilities" aria-label="Permalink to &quot;New Capabilities&quot;">​</a></h3><p>Each domain becomes a discrete spec in the Specs phase:</p><ul><li><code>auth-onboarding</code>: Login, Signup, Tenant Wizard, Tenant Switcher</li><li><code>system-config</code>: Exchange Rates, Document Types, Payment Methods, Plans, Plan-Menu Assignment</li><li><code>org-config</code>: Org Profile, Payment Methods, Roles, Permissions Matrix, Currency History, Expense Categories, Expenses</li><li><code>user-profile</code>: Profile, Preferences</li><li><code>crm</code>: Client Search (global), Client Profile (global), CRM List (tenant), CRM Contact Detail, Client Records</li><li><code>hr</code>: Employee Search (global), Employee Profile (global), Staff Directory, Contract Detail, Attendance Dashboard</li><li><code>services-catalog</code>: Service Catalog, Resource Inventory, Service-Resource Mapping, Employee Skills, Commission Overrides</li><li><code>scheduling</code>: Employee Working Hours, Employee Time Off, Resource Hours, Resource Time Off, Conflict Dashboard</li><li><code>queue</code>: Queue Config, Kiosk/Totem, Queue Board Display, Queue Reception Control</li><li><code>appointments</code>: Booking Calendar, New Appointment, Appointment Detail/Edit, Today&#39;s Agenda, Client Booking Widget</li><li><code>financial</code>: Payment/Checkout, Payment History, Commission Registry, Commission Payout, Commission Dashboard</li><li><code>reviews</code>: Review Submission, Review Dashboard</li><li><code>reports</code>: Executive Dashboard, Appointment Analytics, Financial P&amp;L</li></ul><h3 id="modified-capabilities" tabindex="-1">Modified Capabilities <a class="header-anchor" href="#modified-capabilities" aria-label="Permalink to &quot;Modified Capabilities&quot;">​</a></h3><p>None — no existing specs to modify.</p><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><ol><li>Derive screens in topological order: master tables → tenant config → global identities → identity-tenant relations → resources/services → scheduling → queues → transactions</li><li>Map each screen to <code>SystemMenu</code> transaction codes (<code>CFG-*</code>, <code>CRM-*</code>, <code>HRM-*</code>, <code>SER-*</code>, <code>SCH-*</code>, <code>QUE-*</code>, <code>FIN-*</code>, <code>REP-*</code>) and <code>OrganizationRoleMenu</code> permission checkboxes</li><li>Define nav tree from <code>SystemMenu</code> parent-child hierarchy, filtered by <code>PlanMenu</code> → <code>OrganizationRoleMenu</code></li><li>Document cross-cutting patterns: tenant switching middleware, CRM privacy fallback, real-time subscriptions, calendar availability, kiosk isolation</li></ol><h2 id="estimated-screens-by-domain" tabindex="-1">Estimated Screens by Domain <a class="header-anchor" href="#estimated-screens-by-domain" aria-label="Permalink to &quot;Estimated Screens by Domain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain</th><th>Screens</th><th>Complexity</th></tr></thead><tbody><tr><td>Auth &amp; Onboarding</td><td>4</td><td>Medium</td></tr><tr><td>System Config</td><td>5</td><td>Low</td></tr><tr><td>Org Config</td><td>7</td><td>High (perm matrix)</td></tr><tr><td>User Profile</td><td>2</td><td>Low</td></tr><tr><td>CRM</td><td>5</td><td>Medium</td></tr><tr><td>HR</td><td>5</td><td>Medium</td></tr><tr><td>Services &amp; Resources</td><td>5</td><td>Medium</td></tr><tr><td>Scheduling</td><td>5</td><td>High (availability)</td></tr><tr><td>Queue / Walk-in</td><td>4</td><td>Medium (real-time)</td></tr><tr><td>Appointments &amp; Booking</td><td>5</td><td>Critical (calendar)</td></tr><tr><td>Financial &amp; Reviews</td><td>9</td><td>High (audit trail)</td></tr><tr><td>Reports &amp; Analytics</td><td>3</td><td>Medium</td></tr><tr><td><strong>Total</strong></td><td><strong>71</strong></td><td></td></tr></tbody></table><h2 id="key-architectural-decisions-to-validate" tabindex="-1">Key Architectural Decisions to Validate <a class="header-anchor" href="#key-architectural-decisions-to-validate" aria-label="Permalink to &quot;Key Architectural Decisions to Validate&quot;">​</a></h2><ol><li><strong>Navigation tree</strong> — <code>SystemMenu</code> → filtered by <code>PlanMenu</code> → <code>OrganizationRoleMenu</code> per user role</li><li><strong>Calendar availability</strong> — Edge Function vs DB function for multi-constraint slot computation</li><li><strong>Kiosk route</strong> — separate <code>/kiosk</code> with touch-optimized layout, no sidebar</li><li><strong>CRM privacy fallback</strong> — local field → global field display logic for email/phone</li><li><strong>Real-time</strong> — Supabase Realtime for Queue Board and Booking Calendar</li><li><strong>Tenant switching</strong> — <code>app.current_tenant_id</code> + <code>app.current_user_role_id</code> middleware</li></ol><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Mitigation</th></tr></thead><tbody><tr><td>Calendar engine — most complex piece (employee + resource + service × working hours × timeoff × existing appointments)</td><td>High</td><td>Dedicated Edge Function, do not use raw SQL</td></tr><tr><td>71 screens = large effort without a UI kit</td><td>High</td><td>Recommend Angular Material / PrimeNG</td></tr><tr><td>No routing library installed</td><td>Medium</td><td>Spec phase to recommend TanStack Router or Angular Router</td></tr><tr><td>No test suite</td><td>Medium</td><td>Recommend Vitest + Testing Library in task phase</td></tr></tbody></table><h2 id="rollback-plan" tabindex="-1">Rollback Plan <a class="header-anchor" href="#rollback-plan" aria-label="Permalink to &quot;Rollback Plan&quot;">​</a></h2><p>Analysis-only proposal — no code to roll back. If entity→screen mapping is incorrect, update <code>proposal.md</code> and re-run the Spec phase with corrections.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><code>modelo-datos-bookia-v2.md</code> — data model source of truth (complete)</li><li><code>exploration.md</code> — screen inventory analysis at <code>C:\\Users\\PC\\Desktop\\supabase\\exploration.md</code> (complete)</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[ ] All ~30 tables mapped to at least one screen</li><li>[ ] Every screen has: purpose, data source, CRUD type, key fields, permissions, nav parent</li><li>[ ] Navigation tree aligns with <code>SystemMenu</code> hierarchy and transaction codes</li><li>[ ] CRM privacy fallback pattern documented for all client/employee contact display</li><li>[ ] Calendar availability constraints captured as screen requirements</li></ul><h2 id="decision-log" tabindex="-1">Decision Log <a class="header-anchor" href="#decision-log" aria-label="Permalink to &quot;Decision Log&quot;">​</a></h2><p><em>(Empty — will be filled as decisions are made in spec/design phases)</em></p>',30)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
